package coremain

import (
	"net/url"
	"strings"
)

// WARNING: this file contains deployment credentials. Do not publish it
// outside the intended deployment tree.
//
// These are the deployment credentials for the built-in customBrowser
// control plane. The client identity is still generated by the server and
// persisted in identity_file; only the bootstrap credentials are fixed here.
const (
	builtinProxyProvideControlToken = "cbak_d0bdd377caa3bd2e820160af256692c3550a844df149d1e1984972965ae314c2"
	builtinProxyProvideNodeToken    = "vyos-edge-auth-token-2026"
)

type builtinProxyProvideAuth struct {
	controlToken string
	nodeToken    string
}

var builtinProxyProvideAuthByHost = map[string]builtinProxyProvideAuth{
	"api.aa2.dev": {controlToken: builtinProxyProvideControlToken, nodeToken: builtinProxyProvideNodeToken},
	"api.aa3.dev": {controlToken: builtinProxyProvideControlToken, nodeToken: builtinProxyProvideNodeToken},
}

// builtinProxyProvideAuthFor returns the embedded bootstrap credentials for a
// known built-in control-plane host. Unknown hosts keep the normal semantics:
// an empty token means no Authorization header.
func builtinProxyProvideAuthFor(domain string) (builtinProxyProvideAuth, bool) {
	u, err := url.Parse(strings.TrimSpace(domain))
	if err != nil {
		return builtinProxyProvideAuth{}, false
	}
	auth, ok := builtinProxyProvideAuthByHost[strings.ToLower(u.Hostname())]
	return auth, ok
}
